    if(rack.x < minX + margin) minX = rack.x - margin;
    if(rack.y < minY + margin) minY = rack.y - margin;
    if(rack.x + rack.w > maxX - margin) maxX = rack.x + rack.w + margin;
    if(rack.y + rack.h > maxY - margin) maxY = rack.y + rack.h + margin;
