    'porcelain-gray':{label:'Porcelanato gris 60×60',color:'#c3c7c7',grout:'#929a9c',size:60},
    'marble':{label:'Porcelanato mármol claro',color:'#e8e8e3',grout:'#b7b9b4',size:60},
