    const aMid=a.map((p,i)=>({x:(p.x+a[(i+1)%a.length].x)/2,y:(p.y+a[(i+1)%a.length].y)/2}));
    const bMid=b.map((p,i)=>({x:(p.x+b[(i+1)%b.length].x)/2,y:(p.y+b[(i+1)%b.length].y)/2}));
