      {x:c.x-dir.x*half-n.x*depth,y:c.y-dir.y*half-n.y*depth},{x:c.x+dir.x*half-n.x*depth,y:c.y+dir.y*half-n.y*depth},
      {x:c.x+dir.x*half+n.x*depth,y:c.y+dir.y*half+n.y*depth},{x:c.x-dir.x*half+n.x*depth,y:c.y-dir.y*half+n.y*depth}
